package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
)

type User struct {
	Name string `form:"name" json:"name"`
	Age  int    `form:"age" json:"age"`
}

func main() {
	r := gin.New()
	r.POST("/users", func(c *gin.Context) {
		var u User
		// Content-Type 是 JSON 就用 JSON 绑定，否则用表单绑定
		if err := c.ShouldBind(&u); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, u)
	})

	// 表单提交：Content-Type 是 x-www-form-urlencoded
	formReq := httptest.NewRequest(http.MethodPost, "/users", strings.NewReader("name=tom&age=18"))
	formReq.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	formW := httptest.NewRecorder()
	r.ServeHTTP(formW, formReq)
	fmt.Println("form:", formW.Code, formW.Body.String())

	// JSON 提交：同一段代码照样能绑
	jsonReq := httptest.NewRequest(http.MethodPost, "/users", strings.NewReader(`{"name":"tom","age":18}`))
	jsonReq.Header.Set("Content-Type", "application/json")
	jsonW := httptest.NewRecorder()
	r.ServeHTTP(jsonW, jsonReq)
	fmt.Println("json:", jsonW.Code, jsonW.Body.String())
}

