type Item struct {
	Name  string `json:"name" binding:"required"`
	Count int    `json:"count" binding:"gte=0"`
}

func main() {
	r := gin.New()
	// JSON 数组绑到切片
	r.POST("/items", func(c *gin.Context) {
		var items []Item
		if err := c.ShouldBindJSON(&items); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, items)
	})
	// 表单里重复的参数绑到切片
	r.POST("/ids", func(c *gin.Context) {
		var q struct {
			IDs []int `form:"ids"`
		}
		if err := c.ShouldBind(&q); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, q.IDs)
	})

	body := `[{"name":"a","count":1},{"name":"b","count":2}]`
	req := httptest.NewRequest(http.MethodPost, "/items", strings.NewReader(body))
	req.Header.Set("Content-Type", "application/json")
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	fmt.Println("/items:", w.Code, w.Body.String())

	req2 := httptest.NewRequest(http.MethodPost, "/ids?ids=1&ids=2", nil)
	w2 := httptest.NewRecorder()
	r.ServeHTTP(w2, req2)
	fmt.Println("/ids:", w2.Code, w2.Body.String())
