package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
)

// form 给表单绑定，json 给 JSON 绑定，uri 给路径绑定，binding 给校验器
type User struct {
	Name string `form:"name" json:"name" binding:"required,min=2,max=16"`
	Age  int    `form:"age" json:"age" binding:"gte=0,lte=150"`
	Role string `form:"role" json:"role" binding:"required,oneof=admin editor guest"`
}

// 路径参数单独一个结构体，只绑路由里的占位符
type UserPath struct {
	Name string `uri:"name"`
}

func main() {
	r := gin.New()

	// JSON 请求体：绑定加校验
	r.POST("/users", func(c *gin.Context) {
		var u User
		if err := c.ShouldBindJSON(&u); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusCreated, u)
	})

	// 查询参数：分页
	r.GET("/users", func(c *gin.Context) {
		var q struct {
			Page int `form:"page"`
		}
		if err := c.ShouldBindQuery(&q); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, q)
	})

	// 路径参数：路由里的 :name
	r.GET("/users/:name", func(c *gin.Context) {
		var p UserPath
		if err := c.ShouldBindUri(&p); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, p)
	})

	body := `{"name":"tom","age":18,"role":"admin"}`
	req := httptest.NewRequest(http.MethodPost, "/users", strings.NewReader(body))
	req.Header.Set("Content-Type", "application/json")
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	fmt.Println("POST /users ->", w.Code, w.Body.String())

	req2 := httptest.NewRequest(http.MethodGet, "/users/tom?page=2", nil)
	w2 := httptest.NewRecorder()
	r.ServeHTTP(w2, req2)
	fmt.Println("GET /users/tom ->", w2.Code, w2.Body.String())
}
